import { Context } from '@temporalio/activity';
import { ec2Client } from '../lib/aws';
import { DeleteVpcPeeringConnectionCommand } from '@aws-sdk/client-ec2';
import { db } from '../lib/db';

export async function deprovisionVpcPeeringActivity(input: {
  peeringConnectionId: string;
  tenantIdentifier: string;
}): Promise<{ status: string }> {
  const { peeringConnectionId, tenantIdentifier } = input;

  const verified = await db.query(
    'SELECT id FROM tenant_vpc_peerings WHERE peering_id = $1 AND tenant_id = $2',
    [peeringConnectionId, tenantIdentifier]
  );
  if (verified.rowCount === 0) {
    throw new Error('Forbidden: peering connection does not belong to specified tenant');
  }

  const command = new DeleteVpcPeeringConnectionCommand({
    VpcPeeringConnectionId: peeringConnectionId
  });
  await ec2Client.send(command);

  return { status: 'DELETED' };
}
